export function mountRealCatalog(api){const host=document.createElement('section');host.id='realBoardCatalog';host.innerHTML=`<div class="catalogHeading"><div><span class="studioKicker">ARCHIVO DE PLACAS REALES · FUENTES VERIFICADAS 12 OCT 2026</span><h2>Un modelo. Una revisión. Su documentación.</h2><p>Abre el banco 3D cuando hay datos importados o consulta el esquema y la implantación del fabricante. Los planos de posición no incluyen por sí solos las pistas internas.</p></div><span class="catalogCount">${realBoards.length}<small>modelos documentados</small></span></div><div class="catalogFilters"><input id="realSearch" type="search" placeholder="Buscar modelo, fabricante o familia…" aria-label="Buscar placa real"><select id="realFamily" aria-label="Familia de placas"><option value="">Todas las familias</option>${[...new Set(realBoards.map(b=>b.family))].map(f=>`<option>${f}</option>`).join('')}</select></div><div id="realCards" class="realCards"></div><p class="catalogBoundary">Las placas de referencia de electrodomésticos se estudian mediante documentación. No se simulan mediciones energizadas de red. Los modelos genéricos de TV, teléfono, tablet y lavadora del banco siguen identificados como arquitecturas didácticas.</p>`;document.querySelector('#libraryPage').prepend(host);mountPlayableBoards(host,api);const $=id=>host.querySelector('#'+id);function render(){const q=$('realSearch').value.toLowerCase(),family=$('realFamily').value;const items=realBoards.filter(b=>(!family||b.family===family)&&`${b.name} ${b.maker} ${b.family}`.toLowerCase().includes(q));$('realCards').innerHTML=items.map(b=>`<article class="realCard"><div class="realCardTop"><span>${esc(b.family)}</span><b>${b.board?'3D + CAD':'DOCUMENTOS'}</b></div><small>${esc(b.maker)}</small><h3>${esc(b.name)}</h3><p class="realRevision">${esc(b.revision)}</p><p>${esc(b.note)}</p><details><summary>Qué practicar en esta placa</summary><ol>${b.tasks.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></details><div class="realLinks">${b.board?`<button data-board="${b.board}" class="academyPrimary">Inspeccionar en 3D →</button>`:''}${b.links.map(([title,url])=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`).join('')}</div></article>`).join('')||'<p>No hay placas que coincidan.</p>';$('realCards').querySelectorAll('[data-board]').forEach(btn=>btn.onclick=()=>api.open(btn.dataset.board));}for(const id of ['realSearch','realFamily'])$(id).addEventListener(id==='realSearch'?'input':'change',render);render();const archive=document.createElement('details');archive.className='referenceArchive';archive.innerHTML='<summary>Documentación de fabricantes y revisiones · algunas sin modelo 3D</summary>';[...host.children].filter(el=>!el.classList.contains('playableHeading')).forEach(el=>archive.append(el));host.append(archive);}

function mountPlayableBoards(host,api){
 if(!api.boards?.length)return;const playable=[...api.boards].sort((a,b)=>Number(!!(a.representative||a.educational))-Number(!!(b.representative||b.educational)));const section=document.createElement('section');section.className='playableHeading';
 const thumb=boardThumbnail;
 section.innerHTML=`<span class="studioKicker">${api.boards.length} PLACAS PARA EXPLORAR AHORA</span><h2>Elige tu placa y entra en el banco 3D.</h2><p>Todas las tarjetas de esta galería abren un modelo interactivo. Dentro del banco, pulsa una función para resaltar sus componentes.</p><label>Mostrar <select id="playableFilter"><option value="all">Todas las placas disponibles</option><option value="real">Solo placas con CAD real</option><option value="training">Arquitecturas didácticas</option></select></label><div class="playableGrid">${playable.map(b=>`<article class="playableCard" data-fidelity="${b.representative||b.educational?'training':'real'}">${thumb(b)}<div><small>${b.representative||b.educational?'ARQUITECTURA DIDÁCTICA':'POSICIONES Y REDES DEL CAD REAL'}</small><h3>${esc(b.title)}</h3><p>${b.elements.length} componentes · ${(b.blocks||[]).length} bloques funcionales<br>${b.representative||b.educational?'Modelo de entrenamiento, sin revisión comercial.':'Cuerpos 3D aproximados sobre el diseño importado.'}</p><button data-play="${esc(b.id)}">Abrir placa 3D →</button></div></article>`).join('')}</div><hr>`;
 host.prepend(section);section.querySelector('#playableFilter').onchange=e=>section.querySelectorAll('.playableCard').forEach(card=>card.hidden=e.target.value!=='all'&&card.dataset.fidelity!==e.target.value);section.querySelectorAll('[data-play]').forEach(btn=>btn.onclick=()=>api.open(btn.dataset.play));
}
